// Moore-type finite state machine to implement HDLC framing.
module TopModule(input clk, input reset, input in, output reg disc, output reg flag, output reg err);
  reg [2:0] cnt;
  reg [2:0] sreg;
  reg [2:0] next_sreg;
  always @(*) begin
    case (sreg)
      3'b000: next_sreg = in ? 3'b001 : 3'b000;
      3'b001: next_sreg = in ? 3'b010 : 3'b000;
      3'b010: next_sreg = in ? 3'b011 : 3'b000;
      3'b011: next_sreg = in ? 3'b100 : 3'b000;
      3'b100: next_sreg = in ? 3'b101 : 3'b000;
      3'b101: next_sreg = in ? 3'b110 : 3'b000;
      3'b110: next_sreg = in ? 3'b111 : 3'b000;
      3'b111: next_sreg = in ? 3'b000 : 3'b100;
    endcase
  end
  always @(posedge clk) begin
    if (reset) begin
      sreg <= 3'b000;
      cnt <= 3'b000;
      disc <= 1'b0;
      flag <= 1'b0;
      err <= 1'b0;
    end else begin
      sreg <= next_sreg;
      cnt <= (sreg == 3'b011) ? cnt + 3'b001 : (sreg == 3'b111) ? 3'b000 : cnt;
      disc <= (sreg == 3'b001) & (cnt == 3'b000);
      flag <= (sreg == 3'b011) & (cnt == 3'b010);
      err <= (sreg == 3'b111) & (cnt >= 3'b011);
    end
  end
endmodule

