// Synchronous HDLC framing, see above. The FSM is a Moore type,
// i.e., the output is determined solely by the current state and
// input.
module TopModule(
    input  clk,
    input  reset,
    input  in,
    output reg disc,
    output reg flag,
    output reg err
);
    reg [2:0] count;
    reg [2:0] state;
    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            state <= 3'b001;
            disc <= 0;
            flag <= 0;
            err <= 0;
        end else begin
            case (state)
                3'b001: begin
                    if (in) begin
                        count <= count + 1;
                        state <= 3'b010;
                    end else begin
                        count <= 1;
                        state <= 3'b001;
                    end
                end
                3'b010: begin
                    if (in) begin
                        count <= count + 1;
                        if (count == 6) begin
                            count <= 1;
                            state <= 3'b011;
                            disc <= 1;
                        end else begin
                            state <= 3'b010;
                        end
                    end else begin
                        count <= 1;
                        state <= 3'b001;
                    end
                end
                3'b011: begin
                    if (in) begin
                        count <= count + 1;
                        if (count == 7) begin
                            count <= 1;
                            state <= 3'b100;
                            err <= 1;
                        end else begin
                            state <= 3'b011;
                        end
                    end else begin
                        count <= 1;
                        state <= 3'b001;
                    end
                end
                3'b100: begin
                    if (in) begin
                        count <= count + 1;
                        if (count == 8) begin
                            count <= 1;
                            state <= 3'b101;
                            flag <= 1;
                        end else begin
                            state <= 3'b100;
                        end
                    end else begin
                        count <= 1;
                        state <= 3'b001;
                    end
                end
                3'b101: begin
                    if (in) begin
                        count <= count + 1;
                        if (count == 9) begin
                            count <= 1;
                            state <= 3'b001;
                        end else begin
                            state <= 3'b101;
                        end
                    end else begin
                        count <= 1;
                        state <= 3'b001;
                    end
                end
            endcase
            disc <= 0;
            flag <= 0;
            err <= 0;
        end
    end
endmodule

