// Synchronous HDLC framing, with explicit discard, flag, and error signals.
// The FSM is a Moore-type finite state machine, recognizing three sequences:
// (1) 0111110: Signal a bit needs to be discarded.
// (2) 01111110: Flag the beginning/end of a frame.
// (3) 01111111...: Error (7 or more 1s).
module TopModule(
    input  clk,
    input  reset,
    input  in,
    output reg disc,
    output reg flag,
    output reg err
);
    reg [2:0] cnt;
    reg [1:0] state, nextstate;
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b01;
            cnt <= 3'b000;
            disc <= 1'b0;
            flag <= 1'b0;
            err <= 1'b0;
        end else begin
            state <= nextstate;
            case (state)
                2'b00: if (in) begin cnt <= 3'b001; nextstate = 2'b01; end
                2'b01: begin
                    if (in) begin cnt <= cnt + 1'b1; end
                    else begin cnt <= 3'b000; nextstate = 2'b10; end
                end
                2'b10: begin
                    if (in) begin cnt <= cnt + 1'b1; end
                    else begin
                        if (cnt == 3'b010) begin nextstate = 2'b00; disc <= 1'b1; end
                        else if (cnt == 3'b011) begin nextstate = 2'b00; flag <= 1'b1; end
                        else if (cnt >= 3'b100) begin nextstate = 2'b00; err <= 1'b1; end
                        else begin nextstate = 2'b00; end
                        cnt <= 3'b000;
                    end
                end
            endcase
        end
    end
endmodule

