module TopModule(
    input  clk,
    input  reset,
    input  in,
    output reg disc,
    output reg flag,
    output reg err
);
    reg [2:0] count;
    reg last;
    reg [1:0] state, next_state;
    always @(*) begin
        case (state)
            2'b00: next_state = in ? 2'b01 : 2'b00;
            2'b01: next_state = in ? 2'b10 : 2'b00;
            2'b10: next_state = in ? 2'b11 : 2'b00;
            2'b11: next_state = in ? 2'b00 : 2'b00;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            count <= 3'd0;
            last <= 1'b0;
            disc <= 1'b0;
            flag <= 1'b0;
            err <= 1'b0;
        end else begin
            state <= next_state;
            case (state)
                2'b00: begin
                    count <= 3'd0;
                    last <= in;
                    disc <= 1'b0;
                    flag <= 1'b0;
                    err <= 1'b0;
