// Moore-type finite state machine to frame synchronous HDLC: disc, flag, err
module TopModule (
    input  clk,
    input  reset,
    input  in,
    output reg disc,
    output reg flag,
    output reg err
);
    reg [2:0] cnt;
    reg [2:0] state;
    parameter IDLE = 3'd0;
    parameter WAIT_FRAME = 3'd1;
    parameter WAIT_FLAG = 3'd2;
    parameter ERROR = 3'd3;
    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            cnt <= 3'd0;
            disc <= 1'b0;
            flag <= 1'b0;
            err <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (in) begin
                        state <= WAIT_FRAME;
                        cnt <= 3'd1;
                    end
                end
                WAIT_FRAME: begin
                    if (in) begin
                        cnt <= cnt + 1;
                        if (cnt == 3'd5) begin
                            disc <= 1'b1;
                            cnt <= 3'd0;
                        end
                        if (cnt == 3'd6) state <= IDLE;
                    end else begin
                        state <= ERROR;
                    end
                end
                WAIT_FLAG: begin
                    if (in) begin
                        cnt <= cnt + 1;
                        if (cnt == 3'd7) begin
                            flag <= 1'b1;
                            cnt <= 3'd0;
                        end
                        if (cnt == 3'd8) state <= IDLE;
                    end else begin
                        state <= ERROR;
                    end
                end
                ERROR: begin
                    if (in) begin
                        cnt <= cnt + 1;
                        if (cnt > 3'd7) begin
                            err <= 1'b1;
                            cnt <= 3'd0;
                        end
                    end else begin
                        state <= IDLE;
                        cnt <= 3'd0;
                    end
                end
            endcase
        end
    end
    always @(posedge clk) begin
        if (reset) disc <= 1'b0;
        else if (state == WAIT_FRAME && cnt == 3'd6) disc <= 1'b0;
    end
    always @(posedge clk) begin
        if (reset) flag <= 1'b0;
        else if (state == WAIT_FLAG && cnt == 3'd7) flag <= 1'b0;
    end
    always @(posedge clk) begin
        if (reset) err <= 1'b0;
        else if (state == ERROR) err <= 1'b0;
    end
endmodule

